<?php get_header(); ?><section class="wrap"><h1><?php echo is_home()?'Journal':esc_html(get_the_archive_title()); ?></h1><div class="post-grid"><?php while(have_posts()):the_post(); ?><article class="post-card"><a href="<?php the_permalink(); ?>"><?php if(has_post_thumbnail())the_post_thumbnail('medium_large'); ?><h3><?php the_title(); ?></h3></a><p><?php echo esc_html(wp_trim_words(get_the_excerpt(),24)); ?></p></article><?php endwhile; ?></div><?php the_posts_pagination(); ?></section><?php get_footer(); ?>